<?php
namespace App\Http\Controllers;
use App\Services\WorkspaceContext as W;
use App\Models\Tenant;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Facades\Hash;
use Illuminate\Support\Facades\Mail;
use Illuminate\Support\Str;
class WorkspaceController extends Controller {
 public function index(){W::authorize('settings.view');return view('crm.settings',['tenant'=>W::tenant(),'members'=>DB::table('memberships')->join('users','users.id','=','memberships.user_id')->where('memberships.tenant_id',W::id())->select('users.id','users.name','users.email','memberships.role')->get(),'invitations'=>DB::table('invitations')->where('tenant_id',W::id())->get(),'availableRoles'=>\App\Services\RoleService::roles(W::id()),'keys'=>DB::table('api_keys')->where('tenant_id',W::id())->select('id','name','last_used_at','expires_at')->get()]);}
 public function choose(Request $r){$d=$r->validate(['tenant_id'=>'required|integer']);abort_unless(DB::table('memberships')->where('tenant_id',$d['tenant_id'])->where('user_id',$r->user()->id)->exists(),403);$r->session()->put('tenant_id',$d['tenant_id']);return redirect()->route('dashboard');}
 public function update(Request $r){W::authorize('settings.manage');$d=$r->validate(['name'=>'required|string|max:255','timezone'=>'required|timezone']);W::tenant()->update($d);return back()->with('success','Workspace updated.');}
 public function invite(Request $r){W::authorize('team.manage');$d=$r->validate(['email'=>'required|email|max:255','role'=>['required',\Illuminate\Validation\Rule::exists('tenant_roles','slug')->where('tenant_id',W::id())]]);$plan=DB::table('subscriptions')->leftJoin('plans','plans.id','=','subscriptions.plan_id')->where('subscriptions.tenant_id',W::id())->value('plans.seat_limit');$maxSeats=$plan? (int)$plan:5;$occupied=DB::table('memberships')->where('tenant_id',W::id())->count();$pending=DB::table('invitations')->where('tenant_id',W::id())->where('expires_at','>',now())->count();abort_unless($occupied+$pending<$maxSeats,422,'Your plan seat limit has been reached.');$roleId=DB::table('tenant_roles')->where('tenant_id',W::id())->where('slug',$d['role'])->value('id');abort_unless($roleId && \App\Services\RoleService::canAssign(W::id(),(int)auth()->id(),(int)$roleId),403,'Cannot grant a role more privileged than your own.');$token=Str::random(64);DB::table('invitations')->insert(['tenant_id'=>W::id(),'email'=>strtolower($d['email']),'role'=>$d['role'],'token_hash'=>hash('sha256',$token),'expires_at'=>now()->addDays(7),'created_at'=>now(),'updated_at'=>now()]);$url=route('invitation.accept',['token'=>$token]);Mail::raw('You have been invited to Fida CRM. Accept your invitation: '.$url,fn($m)=>$m->to($d['email'])->subject('Fida CRM invitation'));return back()->with('success','Invitation saved and submitted to the configured mail transport.');}
 public function accept(Request $r,string $token){abort_unless($r->user(),403);$invite=DB::table('invitations')->where('token_hash',hash('sha256',$token))->where('expires_at','>',now())->first();abort_unless($invite,404);abort_unless(strcasecmp($r->user()->email,$invite->email)===0,403,'Sign in with the invited email address.');DB::transaction(function()use($invite,$r){ $roleId=DB::table('tenant_roles')->where('tenant_id',$invite->tenant_id)->where('slug',$invite->role)->value('id');abort_unless($roleId,422,'Role no longer exists.');abort_unless(!DB::table('memberships')->where('tenant_id',$invite->tenant_id)->where('user_id',$r->user()->id)->where('role','owner')->exists(),403,'Workspace ownership cannot be changed through an invitation.');DB::table('memberships')->updateOrInsert(['tenant_id'=>$invite->tenant_id,'user_id'=>$r->user()->id],['role'=>$invite->role,'role_id'=>$roleId,'created_at'=>now(),'updated_at'=>now()]);DB::table('invitations')->where('id',$invite->id)->delete();});$r->session()->put('tenant_id',$invite->tenant_id);return redirect()->route('dashboard');}
 public function role(Request $r,int $user){W::authorize('team.manage');abort_if($r->user()->id===$user,422,'Cannot change your own role.');$d=$r->validate(['role'=>['required',\Illuminate\Validation\Rule::exists('tenant_roles','slug')->where('tenant_id',W::id())]]);abort_if($d['role']==='owner',403);$roleId=DB::table('tenant_roles')->where('tenant_id',W::id())->where('slug',$d['role'])->value('id');$existingRole=DB::table('memberships')->where('tenant_id',W::id())->where('user_id',$user)->value('role_id');abort_unless($roleId && \App\Services\RoleService::canAssign(W::id(),(int)auth()->id(),(int)$roleId) && (!$existingRole || \App\Services\RoleService::canAssign(W::id(),(int)auth()->id(),(int)$existingRole)),403,'Cannot grant or modify a role more privileged than your own.');DB::table('memberships')->where('tenant_id',W::id())->where('user_id',$user)->where('role','!=','owner')->update(['role'=>$d['role'],'role_id'=>$roleId,'updated_at'=>now()]);return back()->with('success','Role updated.');}
 public function makeKey(Request $r){W::authorize('api.manage');$d=$r->validate(['name'=>'required|string|max:120']);$raw='fida_'.Str::random(64);DB::table('api_keys')->insert(['tenant_id'=>W::id(),'user_id'=>$r->user()->id,'name'=>$d['name'],'token_hash'=>hash('sha256',$raw),'abilities'=>'["read","write"]','created_at'=>now(),'updated_at'=>now()]);return back()->with('new_api_token',$raw);}
 public function revokeKey(int $id){W::authorize('api.manage');DB::table('api_keys')->where('tenant_id',W::id())->where('id',$id)->delete();return back()->with('success','API key revoked.');}
 public function new(){return view('crm.new-workspace');}
 public function create(Request $r){$d=$r->validate(['name'=>'required|string|max:255']);$tenant=app(\App\Services\WorkspaceProvisioner::class)->create($d['name'],$r->user()->id);$r->session()->put('tenant_id',$tenant->id);return redirect()->route('dashboard');}
}
